/// <summary>
/// Change Item Status
/// </summary>
internal final class METChangeItemStatus
{
    #OCCRetryCount
    METInventItemOrderSetup metInventItemOrderSetup;
    InventItemPurchSetup inventItemPurchSetup;
    InventParameters inventParameters = InventParameters::find();

}

