/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    try
    {
        ttsbegin;
        METChangeItemStatus metChangeItemStatus = new METChangeItemStatus();
        FormRun formRun = _args.caller();

        if (_args && _args.parmEnumType() == enumNum(METItemsStatus))
        {
            metChangeItemStatus.parmMETInventItemOrderSetup(formRun.dataSource(formdatasourcestr(InventItemOrderSetup, METInventItemOrderSetup)).cursor());
            metChangeItemStatus.parmInventItemPurchSetup(formRun.dataSource(formdatasourcestr(InventItemOrderSetup, InventItemPurchSetup)).cursor());

            switch(_args.parmEnum())
            {
                case METItemsStatus::New :
                    metChangeItemStatus.manualUpdateToNew();
                    formRun.dataSource(formdatasourcestr(InventItemOrderSetup, InventItemPurchSetup)).research(true);
                break;

                case METItemsStatus::Active :
                    metChangeItemStatus.manualUpdateToActive();
                    formRun.dataSource(formdatasourcestr(InventItemOrderSetup, InventItemPurchSetup)).research(true);
                break;

                case METItemsStatus::Discontinued :
                    metChangeItemStatus.updateStatusToDiscontinue(metChangeItemStatus.parmMETInventItemOrderSetup());
                    formRun.dataSource(formdatasourcestr(InventItemOrderSetup, InventItemPurchSetup)).research(true);
                break;

                case METItemsStatus::Deleted :
                    metChangeItemStatus.updateStatusToDelete(metChangeItemStatus.parmMETInventItemOrderSetup());
                    formRun.dataSource(formdatasourcestr(InventItemOrderSetup, InventItemPurchSetup)).research(true);
                break;

                case METItemsStatus::PackChange :
                    metChangeItemStatus.updateStatusToPackChange(metChangeItemStatus.parmMETInventItemOrderSetup());
                    formRun.dataSource(formdatasourcestr(InventItemOrderSetup, InventItemPurchSetup)).research(true);
                break;

                default:
                    break;

            }              

        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch
    {
        throw error("@MET:UnhandledError");
    }
}

/// <summary>
/// Parm method
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
/// <returns>METInventItemOrderSetup</returns>
public METInventItemOrderSetup parmMETInventItemOrderSetup(METInventItemOrderSetup _metInventItemOrderSetup = metInventItemOrderSetup)
{
    metInventItemOrderSetup = _metInventItemOrderSetup;
    return _metInventItemOrderSetup;
}

/// <summary>
/// Parm method for InventItemPurchSetup
/// </summary>
/// <param name = "_inventItemPurchSetup">InventItemPurchSetup</param>
/// <returns>InventItemPurchSetup</returns>
public InventItemPurchSetup parmInventItemPurchSetup(InventItemPurchSetup _inventItemPurchSetup = inventItemPurchSetup)
{
    inventItemPurchSetup = _inventItemPurchSetup;
    return _inventItemPurchSetup;
}

/// <summary>
/// Manual update status to New
/// </summary>
public void manualUpdateToNew()
{
    Set setWarehouse = new Set(Types::String);
    boolean updated;

    if (!metInventItemOrderSetup && inventItemPurchSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;

        metInventItemOrderSetupLocal.ItemId = inventItemPurchSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetup.InventDimId;
        metInventItemOrderSetupLocal.SiteId = inventItemPurchSetup.inventDim().InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        metInventItemOrderSetupLocal.insert();
        info(strFmt("@MET:StatusDoesNotExist", inventItemPurchSetup.inventDim().InventSiteId));
    }
    else if(metInventItemOrderSetup && (metInventItemOrderSetup.ItemStatus == METConstants::Active || metInventItemOrderSetup.ItemStatus == METConstants::emptyString))
    {
        this.updateStatusToNew(metInventItemOrderSetup);
        METInventItemOrderSetup::updateChildItemSiteStatusToNew(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);
        updated = true;

    }

    if (updated)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select InventSiteId, InventLocationId from metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
        && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
        {
            if(InventLocation::find(metReqItemTableInventDimView.InventLocationId).METNDCWarehouse)
            {
                InventLocation inventLocation;

                while select InventLocationId from inventLocation
                where inventLocation.METNDCWarehouse == NoYes::Yes
                {
                    if (!setWarehouse.in(inventLocation.InventLocationId))
                    {
                        setWarehouse.add(inventLocation.InventLocationId);
                    }
                }
            }
            else
            {
                if (!setWarehouse.in(metReqItemTableInventDimView.InventLocationId))
                {
                    setWarehouse.add(metReqItemTableInventDimView.InventLocationId);
                }
            }
        } 

        this.itemStatusToTransferDependSites_New(setWarehouse);
    }        
}

/// <summary>
/// Manual update status to Active
/// </summary>
public void manualUpdateToActive()
{
    Set setWarehouse = new Set(Types::String);
    boolean updated;

    if (!metInventItemOrderSetup && inventItemPurchSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;

        metInventItemOrderSetupLocal.ItemId = inventItemPurchSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetup.InventDimId;
        metInventItemOrderSetupLocal.SiteId = inventItemPurchSetup.inventDim().InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        metInventItemOrderSetupLocal.PublishPriceBook    = true;
        metInventItemOrderSetupLocal.PublishPortal       = true;
        metInventItemOrderSetupLocal.PublishHost         = true;
        metInventItemOrderSetupLocal.insert();
        info(strFmt("@MET:StatusDoesNotExist", inventItemPurchSetup.inventDim().InventSiteId));
    }
    else if (metInventItemOrderSetup && (metInventItemOrderSetup.ItemStatus == METConstants::NewStr || metInventItemOrderSetup.ItemStatus == METConstants::emptyString))
    {
        this.updateStatusToActive(metInventItemOrderSetup);
        METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);
        updated = true;
    }

    if (updated)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select InventSiteId, InventLocationId from metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
        && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
        {
            if (InventLocation::find(metReqItemTableInventDimView.InventLocationId).METNDCWarehouse)
            {
                InventLocation inventLocation;

                while select InventLocationId from inventLocation
                where inventLocation.METNDCWarehouse == NoYes::Yes
                {
                    if (!setWarehouse.in(inventLocation.InventLocationId))
                    {
                        setWarehouse.add(inventLocation.InventLocationId);
                    }
                }
            }
            else
            {
                if (!setWarehouse.in(metReqItemTableInventDimView.InventLocationId))
                {
                    setWarehouse.add(metReqItemTableInventDimView.InventLocationId);
                }
            }
        }

        this.itemStatusToTransferDependSites_Active(setWarehouse);
    }
}

/// <summary>
/// Update status to New to dependent sites
/// </summary>
/// <param name = "_setWarehouse">Set</param>
public void itemStatusToTransferDependSites_New(Set _setWarehouse)
{
    METReqItemTableInventDimView metReqItemTableInventDimView;
    METItemStatusWarehouses metItemStatusWarehouses;

    //Activate all transfer sites
    METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
    metChangeItemStatusHelper.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus);

    //Intercompany case

    if (inventParameters.METInterCompanyPurchaseLegalEntity)
    {
        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
        {
            METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;
            METItemStatusWarehouses metItemStatusWarehousesIntCom;

            while select InventSiteId, InventLocationId, VendIntercompanyWarehouse from metReqItemTableInventDimViewIntCom
                where metReqItemTableInventDimViewIntCom.ItemId == metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimViewIntCom.METInterCompanySourced == NoYes::Yes
                notexists join metItemStatusWarehousesIntCom
                where metItemStatusWarehousesIntCom.InventLocationId == metReqItemTableInventDimViewIntCom.InventLocationId
            {
                if(_setWarehouse.in(metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                {                        
                    this.updateInsertStatusToNew(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, true), metReqItemTableInventDimViewIntCom);
                    METInventItemOrderSetup::updateChildItemSiteStatusToNew(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId);

                    //Activate all transfer sites
                    METChangeItemStatusHelper metChangeItemStatusHelperIntCom = new METChangeItemStatusHelper();
                    metChangeItemStatusHelperIntCom.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus);
                }
            }
        }
    }

}

/// <summary>
/// Update status to New
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
/// <param name = "metReqItemTableInventDimView">METReqItemTableInventDimView</param>
public void updateInsertStatusToNew(METInventItemOrderSetup _metInventItemOrderSetup, METReqItemTableInventDimView _metReqItemTableInventDimView)
{
    if (!_metInventItemOrderSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;
        InventItemPurchSetup inventItemPurchSetupLocal;
        InventDim inventDimLocal;

        select firstonly InventDimId from inventItemPurchSetupLocal
            exists join inventDimLocal
            where inventDimLocal.InventSiteId == _metReqItemTableInventDimView.InventSiteId
            && inventItemPurchSetupLocal.ItemId ==  metInventItemOrderSetup.ItemId
            && inventDimLocal.inventDimId == inventItemPurchSetupLocal.InventDimId;

        metInventItemOrderSetupLocal.ItemId = metInventItemOrderSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetupLocal.InventDimId;
        metInventItemOrderSetupLocal.SiteId = _metReqItemTableInventDimView.InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        metInventItemOrderSetupLocal.PublishPriceBook   = false;
        metInventItemOrderSetupLocal.PublishPortal       = false;
        metInventItemOrderSetupLocal.PublishHost         = false;
        metInventItemOrderSetupLocal.insert();
    }
    else
    {
        _metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        _metInventItemOrderSetup.PublishPriceBook    = false;
        _metInventItemOrderSetup.PublishPortal       = false;
        _metInventItemOrderSetup.PublishHost         = false;
        _metInventItemOrderSetup.update();
    }
}

