/// <summary>
/// Update status to New to dependent sites
/// </summary>
/// <param name = "_setWarehouse">Set</param>
public void itemStatusToTransferDependSites_Active(Set _setWarehouse)
{
    METReqItemTableInventDimView metReqItemTableInventDimView;
    METItemStatusWarehouses metItemStatusWarehouses;


    //Activate all transfer sites
    METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
    metChangeItemStatusHelper.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);

    //Intercompany case 
    if (inventParameters.METInterCompanyPurchaseLegalEntity)
    {
        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
        {
            METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;
            METItemStatusWarehouses metItemStatusWarehousesIntCom;

            while select InventSiteId, InventLocationId, VendIntercompanyWarehouse from metReqItemTableInventDimViewIntCom
                where metReqItemTableInventDimViewIntCom.ItemId == metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimViewIntCom.METInterCompanySourced == NoYes::Yes
                notexists join metItemStatusWarehousesIntCom
                where metItemStatusWarehousesIntCom.InventLocationId == metReqItemTableInventDimViewIntCom.InventLocationId
            {
                if(_setWarehouse.in(metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                {
                    this.updateInsertStatusToActive(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, true), metReqItemTableInventDimViewIntCom);
                    METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId);

                    //Activate all transfer sites
                    METChangeItemStatusHelper metChangeItemStatusHelperIntCom = new METChangeItemStatusHelper();
                    metChangeItemStatusHelperIntCom.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);
                }
            }
        }
    }

}

/// <summary>
/// Update status to Delete
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
public void updateStatusToDelete(METInventItemOrderSetup _metInventItemOrderSetup)
{
    if (!_metInventItemOrderSetup && inventItemPurchSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;

        metInventItemOrderSetupLocal.ItemId = inventItemPurchSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetup.InventDimId;
        metInventItemOrderSetupLocal.SiteId = inventItemPurchSetup.inventDim().InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Deleted).ItemStatus;
        metInventItemOrderSetupLocal.insert();
        info(strFmt("@MET:StatusDoesNotExist", inventItemPurchSetup.inventDim().InventSiteId));
    }
    else if (_metInventItemOrderSetup)
    {
        ttsbegin;
        _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Deleted).ItemStatus;
        _metInventItemOrderSetup.update();
        ttscommit;
    }
}

/// <summary>
/// Update status to Discontinue
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
public void updateStatusToDiscontinue(METInventItemOrderSetup _metInventItemOrderSetup)
{
    if (!_metInventItemOrderSetup && inventItemPurchSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;

        metInventItemOrderSetupLocal.ItemId = inventItemPurchSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetup.InventDimId;
        metInventItemOrderSetupLocal.SiteId = inventItemPurchSetup.inventDim().InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Discontinued).ItemStatus;
        metInventItemOrderSetupLocal.insert();

        this.updateItemStopped(metInventItemOrderSetupLocal.ItemId, metInventItemOrderSetupLocal.InventDimId);

        info(strFmt("@MET:StatusDoesNotExist", inventItemPurchSetup.inventDim().InventSiteId));
    }
    else if (_metInventItemOrderSetup)
    {
        ttsbegin;
        _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Discontinued).ItemStatus;
        _metInventItemOrderSetup.update();

        this.updateItemStopped(_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.InventDimId);
        ttscommit;
    }
}

/// <summary>
/// CB267_ItemStatusAndPackChange_BugFix - Item stopped changes
/// </summary>
/// <param name = "_itemId">Item ID</param>
/// <param name = "_inventDimId">InventDimId</param>
public void updateItemStopped(ItemId _itemId, InventDimId _inventDimId)
{
    InventItemPurchSetup    inventItemPurchSetupLoc;

    ttsbegin;
    update_recordset inventItemPurchSetupLoc
        setting Override = NoYes::Yes, 
                Stopped = NoYes::Yes
        where inventItemPurchSetupLoc.ItemId == _itemId
            && inventItemPurchSetupLoc.InventDimId == _inventDimId;
    ttscommit;
}

